200	    pub(super) async fn attach_live_thread_for_selection(
201	        &mut self,
202	        app_server: &mut AppServerSession,
203	        thread_id: ThreadId,
204	    ) -> Result<bool> {
205	        if self.thread_event_channels.contains_key(&thread_id) {
206	            return Ok(true);
207	        }
208	
209	        let (session, turns, live_attached) = match app_server
210	            .resume_thread(self.config.clone(), thread_id)
211	            .await
212	        {
213	            Ok(started) => (started.session, started.turns, true),
214	            Err(resume_err) => {
215	                tracing::warn!(
216	                    thread_id = %thread_id,
217	                    error = %resume_err,
218	                    "failed to resume live thread for selection; falling back to thread/read"
219	                );
220	                let (thread, turns) = match app_server
221	                    .thread_read(thread_id, /*include_turns*/ true)
222	                    .await
223	                {
224	                    Ok(thread) => {
225	                        let turns = thread.turns.clone();
226	                        (thread, turns)
227	                    }
228	                    Err(err) if Self::can_fallback_from_include_turns_error(&err) => {
229	                        let thread = app_server
230	                            .thread_read(thread_id, /*include_turns*/ false)
231	                            .await?;
232	                        (thread, Vec::new())
233	                    }
234	                    Err(err) => return Err(err),
235	                };
236	                if turns.is_empty() {
237	                    // A `thread/read` fallback without turns would create a blank local replay
238	                    // channel with no live listener attached, which blocks later real re-attach.
239	                    return Err(color_eyre::eyre::eyre!(
240	                        "Agent thread {thread_id} is not yet available for replay or live attach."
241	                    ));
242	                }
243	                let mut session = self.session_state_for_thread_read(thread_id, &thread).await;
244	                // `thread/read` can seed replay state, but it does not attach the app-server
245	                // listener that `thread/resume` establishes, so treat this path as replay-only.
246	                session.model.clear();
247	                (session, turns, false)
248	            }
249	        };
250	        let channel = self.ensure_thread_channel(thread_id);
251	        let mut store = channel.store.lock().await;
252	        store.set_session(session, turns);
253	        Ok(live_attached)
254	    }
